from html.parser import HTMLParser

# Read the page_54.txt file
with open('/app/resources/treasury_bulletin_1953_03_page_54.txt', 'r') as f:
    content = f.read()

# Find the Treasury Bills table
class TreasuryBillParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_tbody = False
        self.current_row = []
        self.in_td = False
        self.current_data = ""
        self.treasury_bills = []

    def handle_starttag(self, tag, attrs):
        if tag == 'tbody':
            self.in_tbody = True
        elif tag == 'tr' and self.in_tbody:
            self.current_row = []
        elif tag == 'td' and self.in_tbody:
            self.in_td = True
            self.current_data = ""

    def handle_endtag(self, tag):
        if tag == 'tbody':
            self.in_tbody = False
        elif tag == 'tr' and self.in_tbody and self.current_row:
            self.treasury_bills.append(self.current_row)
        elif tag == 'td' and self.in_tbody:
            self.current_row.append(self.current_data.strip())
            self.in_td = False

    def handle_data(self, data):
        if self.in_td:
            self.current_data += data

parser = TreasuryBillParser()
parser.feed(content)

# Print the treasury bills found
print("Found", len(parser.treasury_bills), "treasury bill rows")
for bill in parser.treasury_bills[:15]:
    print(bill[:4])
EOF
